mapper.select:
SELECT , NULL AS company_name
  FROM sys12_calendar
 WHERE sys12_company_id = #{companyId}
   AND to_char(sys12_day,'yyyy') = #{year}
   AND (
           (#{month} != '%' AND to_char(sys12_day,'MM') = #{month})
           OR
           (#{month} = '%')
       )
 ORDER BY sys12_day

SELECT , NULL AS company_name
  FROM sys12_calendar
 WHERE sys12_calendar_id = #{calendarId}

mapper.update:
UPDATE sys12_calendar
   SET sys12_working_yn  = #{req.workingYn},
       sys12_off_reason  = #{req.offReason},
       sys12_note        = #{req.note}
 WHERE sys12_calendar_id = #{req.calendarId}
   AND sys12_company_id  = #{companyId}

UPDATE sys12_calendar
   SET sys12_working_yn  = #{req.workingYn},
       sys12_off_reason  = #{req.offReason}
 WHERE sys12_calendar_id = #{req.calendarId}

mapper.delete:
DELETE FROM sys12_calendar
 WHERE sys12_company_id = #{companyId}
   AND to_char(sys12_day,'yyyymmdd') BETWEEN #{startYmd} AND #{endYmd}
